Here is the root cause:
The bug is caused by using linear_page_index(), which returns a page index in PAGE_SIZE (4K) units, in the calculation for hugetlb_fault_mutex_hash() which expects the index in huge page units (e.g., 2M). This mismatch causes different addresses within the same huge page to produce different hash values and thus use different mutexes, leading to race conditions and corruption of the reservation map.

Here is the patch:
  */
 static __always_inline ssize_t mfill_atomic_hugetlb(
 					      struct userfaultfd_ctx *ctx,
 					      struct vm_area_struct *dst_vma,
 					      unsigned long dst_start,
 					      unsigned long src_start,
 					      unsigned long len,
 					      uffd_flags_t flags)
 {
 	struct mm_struct *dst_mm = dst_vma->vm_mm;
 	ssize_t err;
 	pte_t *dst_pte;
 	unsigned long src_addr, dst_addr;
 	long copied;
 	struct folio *folio;
 	unsigned long vma_hpagesize;
 	pgoff_t idx;
 	u32 hash;
 	struct address_space *mapping;

 	/*
 	 * There is no default zero huge page for all huge page sizes as
 	 * supported by hugetlb.  A PMD_SIZE huge pages may exist as used
 	 * by THP.  Since we can not reliably insert a zero page, this
 	 * feature is not supported.
 	 */
 	if (uffd_flags_mode_is(flags, MFILL_ATOMIC_ZEROPAGE)) {
 		up_read(&ctx->map_changing_lock);
 		uffd_mfill_unlock(dst_vma);
 		return -EINVAL;
 	}

 	src_addr = src_start;
 	dst_addr = dst_start;
 	copied = 0;
 	folio = NULL;
 	vma_hpagesize = vma_kernel_pagesize(dst_vma);

 	/*
 	 * Validate alignment based on huge page size
 	 */
 	err = -EINVAL;
 	if (dst_start & (vma_hpagesize - 1) || len & (vma_hpagesize - 1))
 		goto out_unlock;

 retry:
 	/*
 	 * On routine entry dst_vma is set.  If we had to drop mmap_lock and
 	 * retry, dst_vma will be set to NULL and we must lookup again.
 	 */
 	if (!dst_vma) {
 		dst_vma = uffd_mfill_lock(dst_mm, dst_start, len);
 		if (IS_ERR(dst_vma)) {
 			err = PTR_ERR(dst_vma);
 			goto out;
 		}

 		err = -ENOENT;
 		if (!is_vm_hugetlb_page(dst_vma))
 			goto out_unlock_vma;

 		err = -EINVAL;
 		if (vma_hpagesize != vma_kernel_pagesize(dst_vma))
 			goto out_unlock_vma;

 		/*
 		 * If memory mappings are changing because of non-cooperative
 		 * operation (e.g. mremap) running in parallel, bail out and
 		 * request the user to retry later
 		 */
 		down_read(&ctx->map_changing_lock);
 		err = -EAGAIN;
 		if (atomic_read(&ctx->mmap_changing))
 			goto out_unlock;
 	}

 	while (src_addr < src_start + len) {
 		VM_WARN_ON_ONCE(dst_addr >= dst_start + len);

 		/*
 		 * Serialize via vma_lock and hugetlb_fault_mutex.
 		 * vma_lock ensures the dst_pte remains valid even
 		 * in the case of shared pmds.  fault mutex prevents
 		 * races with other faulting threads.
 		 */
-		idx = linear_page_index(dst_vma, dst_addr);
+		idx = hugetlb_linear_page_index(dst_vma, dst_addr);
 		mapping = dst_vma->vm_file->f_mapping;
 		hash = hugetlb_fault_mutex_hash(mapping, idx);
 		mutex_lock(&hugetlb_fault_mutex_table[hash]);
 		hugetlb_vma_lock_read(dst_vma);

 		err = -ENOMEM;
 		dst_pte = huge_pte_alloc(dst_mm, dst_vma, dst_addr, vma_hpagesize);
 		if (!dst_pte) {
 			hugetlb_vma_unlock_read(dst_vma);
 			mutex_unlock(&hugetlb_fault_mutex_table[hash]);
 			goto out_unlock;
 		}

 		if (!uffd_flags_mode_is(flags, MFILL_ATOMIC_CONTINUE)) {
 			const pte_t ptep = huge_ptep_get(dst_mm, dst_addr, dst_pte);

 			if (!huge_pte_none(ptep) && !pte_is_uffd_marker(ptep)) {
 				err = -EEXIST;
 				hugetlb_vma_unlock_read(dst_vma);
 				mutex_unlock(&hugetlb_fault_mutex_table[hash]);
 				goto out_unlock;
 			}
 		}

 		err = hugetlb_mfill_atomic_pte(dst_pte, dst_vma, dst_addr,
 					       src_addr, flags, &folio);

 		hugetlb_vma_unlock_read(dst_vma);
 		mutex_unlock(&hugetlb_fault_mutex_table[hash]);

 		cond_resched();

 		if (unlikely(err == -ENOENT)) {
 			up_read(&ctx->map_changing_lock);
 			uffd_mfill_unlock(dst_vma);
 			VM_WARN_ON_ONCE(!folio);

 			err = copy_folio_from_user(folio,
 						   (const void __user *)src_addr, true);
 			if (unlikely(err)) {
 				err = -EFAULT;
 				goto out;
 			}

 			dst_vma = NULL;
 			goto retry;
 		} else
 			VM_WARN_ON_ONCE(folio);

 		if (!err) {
 			dst_addr += vma_hpagesize;
 			src_addr += vma_hpagesize;
 			copied += vma_hpagesize;

 			if (fatal_signal_pending(current))
 				err = -EINTR;
 		}
 		if (err)
 			break;
 	}

 out_unlock:
 	up_read(&ctx->map_changing_lock);
 out_unlock_vma:
 	uffd_mfill_unlock(dst_vma);
 out:
 	if (folio)
 		folio_put(folio);
 	VM_WARN_ON_ONCE(copied < 0);
 	VM_WARN_ON_ONCE(err > 0);
 	VM_WARN_ON_ONCE(!copied && !err);
 	return copied ? copied : err;
 }
 #else /* !CONFIG_HUGETLB_PAGE */


